import React from 'react';

import UpcScan from '@pohodnik/icons/svg/Commerce/UpcScan';
import { QRCodeSVG } from 'qrcode.react';

import MapPoint from '@components/MapPoint';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingNotes } from '../@services/hikingNotes.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingNote } from '../@types/hikingNotes.types';

const HikingNotesPage: React.FC<{ id_hiking: number }> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [notes, setNotes] = React.useState<IHikingNote[] | null>(null);
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    getHikingDataAsync(id_hiking).then(setHikingData);
    getHikingNotes(id_hiking).then(setNotes);
  }, [id_hiking]);

  if (hikingData == null || notes == null) {
    return <PageLoader />;
  }

  return (
    <div>
      <div className="d-print-none">
        <PohBreadcrumbs
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/notes`, text: 'Заметки', active: true },
          ]}
        />
      </div>

      <PohContainer>
        <header className="d-flex align-items-center justify-content-between">
          <h3>Заметки похода &laquo;{hikingData.name}&raquo;</h3>
          <aside className="d-print-none">
            <PohButton
              icon
              onClick={() => {
                if (!authContext.hash) return alert('has no hash/ try to logout and login again');
                showModal({
                  children: (
                    <div>
                      <h4>QR-код для выгрузки из приложения заметок</h4>
                      <div className="text-center p-5">
                        <QRCodeSVG
                          value={[id_hiking, authContext.hash].join(',')}
                          width={200}
                          height={200}
                        />
                      </div>
                    </div>
                  ),
                });
              }}
            >
              <UpcScan />
            </PohButton>
          </aside>
        </header>
        {notes.length === 0 ? (
          <Empty>Нет заметок</Empty>
        ) : (
          <PohList
            data={notes.map((n) => {
              return {
                key: n.id,
                className: '',
                content: (
                  <PohRow className="align-items-start">
                    <PohCol sm={2} className="d-flex align-items-center">
                      <PohAva src={n.create.user.photo} />
                      <div className="ms-2 me-4">
                        <small className="d-block">
                          {n.create.user.name}&nbsp;{n.create.user.surname}
                        </small>
                        <small className="d-block text-success text-nowrap">
                          {n.create.date.toLocaleString()}
                        </small>
                      </div>
                    </PohCol>
                    <PohCol sm={8} className="flex-grow-1 d-flex">
                      <div className="flex-grow-1">
                        <em style={{ whiteSpace: 'pre-wrap' }}>{n.comment}</em>
                      </div>
                      {n.audio_url && (
                        <span>
                          <a href={n.audio_url}>Audio</a>
                          <audio controls className="ml-auto flex-shrink-0">
                            <source src={n.audio_url} type="audio/webm;codecs=opus" />
                          </audio>
                        </span>
                      )}
                    </PohCol>
                    {n.coordinates.length > 0 && (
                      <PohCol sm={2} className="d-flex align-items-center">
                        <a href={`geo:${n.coordinates}`}>{n.coordinates}</a>&nbsp;
                        <PohButton
                          icon={IconsEnum.open}
                          size={ButtonSize.Small}
                          onClick={() => {
                            showModal({
                              children: (
                                <MapPoint
                                  point={n.coordinates.split(',').map(Number) as [number, number]}
                                  height={400}
                                />
                              ),
                            });
                          }}
                        ></PohButton>
                      </PohCol>
                    )}
                  </PohRow>
                ),
              };
            })}
          />
        )}
      </PohContainer>
    </div>
  );
};

export default HikingNotesPage;
