import { IHikingNotesDTO } from '../@types/DTO/hikingNotes.dto.types';
import { IHikingNote } from '../@types/hikingNotes.types';

export const mapHikingNotes = (backData: IHikingNotesDTO): IHikingNote => {
  return {
    id: +backData.id,
    coordinates: backData.coordinates,
    uploadedAt: new Date(backData.uploaded_at),
    comment: backData.comment,
    audio_url: backData.audio_url ? backData.audio_url : null,
    create: {
      date: new Date(`${backData.created_at}Z`),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
    update: backData.updated_at
      ? {
          date: new Date(backData.updated_at),
          user: {
            id: +backData.updater_id,
            name: backData.updater_name,
            surname: backData.updater_surname,
            photo: backData.updater_photo,
          },
        }
      : null,
  };
};
